# פרק 13 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=13
TITLE='אתיקה ומקצועות המשפט'
SUM=[' <p>היכרות עם בעלי התפקידים בעולם המשפט וכללי ההתנהגות החלים עליהם.</p> <h3>13.1 מקצועות המשפט</h3> <p><strong>עורך דין</strong> (ייצוג וייעוץ), <strong>שופט</strong> (הכרעה ניטרלית), <strong>תובע</strong> (ייצוג המדינה בפלילי), <strong>נוטריון</strong> ו<strong>מגשר/בורר</strong>.</p> <h3>13.2 אתיקה מקצועית</h3> <p>קוד התנהגות מחייב (לעו"ד — חוק לשכת עורכי הדין וכללי האתיקה). חובות מרכזיות: <strong>נאמנות ללקוח</strong>, <strong>חיסיון וסודיות</strong>, איסור <strong>ניגוד עניינים</strong>, ו<strong>הגינות כלפי בית המשפט</strong> (עו"ד כ"קצין בית המשפט").</p> <h3>13.3 אתיקה שיפוטית</h3> <p>על השופט מוטלות חובות <strong>אי-תלות, אובייקטיביות והימנעות ממשוא פנים</strong> — תנאי לאמון הציבור במערכת.</p> <h3>13.4 נקודות מפתח למבחן</h3> <ul><li>תפקידים: עו"ד, שופט, תובע, נוטריון, מגשר.</li><li>אתיקת עו"ד: נאמנות, חיסיון, ניגוד עניינים, הגינות לבית המשפט.</li><li>אתיקה שיפוטית: אי-תלות ואובייקטיביות.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע״א 37/86 לוי נ׳ שרמן, פ״ד מד(4) 446', 'דיון באחריותו של עורך דין כלפי לקוחו בעוולת הרשלנות.', 'נקבע שחוק לשכת עורכי הדין והכללים שהותקנו מכוחו, אף שעניינם אתיקה מקצועית, משמשים מקור לקביעת סטנדרט המיומנות והזהירות שעורך דין חב ללקוחו. כך הנורמה האתית "מתורגמת" לחובת זהירות בנזיקין.'), ('ע״א 7633/12 קבוצת גיאות בע״מ נ׳ גולדפרב לוי ערן מאירי צפריר ושות׳', 'לקוחה תבעה משרד עורכי דין בטענה לרשלנות בייעוץ בסכסוך חוזי. השאלה הייתה מה נדרש מעורך הדין כשהלקוח אינו שועה לעצתו.', 'הערעור נדחה. כשרצון הלקוח מנוגד לייעוץ, על עורך הדין להזהיר את הלקוח ולהסביר את הסיכויים והסיכונים. עוצמת החובה תלויה בזהות הלקוח ומעורבותו, בגודל הסיכון ובמורכבות הסוגיה; התפטרות שמורה למקרי קיצון. חובות ס׳ 54 וכלל 2 משמשות לעיצוב הסטנדרט.'), ('ע״א 2725/91 היינוביץ נ׳ גלעדי, פ״ד מח(3) 92', 'דיון בשאלה אם עורך דין חב חובת זהירות כלפי אדם שאינו לקוחו.', 'הוכר שבנסיבות מסוימות קיימת חובת זהירות של עורך דין גם כלפי צד שלישי שאינו לקוחו. הפסיקה לא קבעה גבולות חדים לחובה, והיקפה נבחן ממקרה למקרה.'), ('על״ע 1734/00 הוועד המחוזי של לשכת עורכי הדין נ׳ שפטל', 'עורך דין התבטא התבטאות פוליטית בחייו הפרטיים, והלשכה טענה שמדובר בהתנהגות שאינה הולמת.', 'נקבעה נוסחת איזון: ככל שהדברים קרובים ל"גרעין הקשה" של המקצוע (כמו הופעה בבית המשפט) נדרש איפוק רב; ככל שהם רחוקים ממנו, משקלו של חופש הביטוי עולה. בנסיבות העניין ניתן משקל רב לחופש הביטוי ונקבע שאין עבירה אתית.'), ('על״ע 8838/00 ניר נ׳ הוועד המחוזי של לשכת עורכי הדין', 'עורך דין פרסם בירחון כתבה שבה ייחס לבתי המשפט לתעבורה "קנוניה" עם המשטרה.', 'ההרשעה בעבירת משמעת נותרה בעינה. הדברים חרגו הרבה מעבר לביקורת לגיטימית ועניינית, ופגעו באמון הציבור ביושרם ובהגינותם של השופטים — פגיעה שעורך דין מחויב להימנע ממנה.'), ('על״ע 736/04 הוועד המחוזי של לשכת עורכי הדין נ׳ מזרחי, פ״ד נח(6) 200', 'עורכת דין שייצגה את עצמה בהליך כתבה בכתבי בי־דין התבטאויות פוגעניות כלפי בית המשפט וכלפי עורך הדין שכנגד.', 'טענת חופש הביטוי נדחתה. נקבע כי המגבלות חלות גם כשעורך הדין מייצג את עצמו או בני משפחתו, חלות ביתר שאת בליבת העיסוק המשפטי, ומגינות הן על בית המשפט והן על העמיתים למקצוע.')]
QS=[{'q': 'מה מבטא ס׳ 54 לחוק לשכת עורכי הדין?', 'o': ['חובה לציית לכל הוראה של הלקוח', 'חובה של עורך הדין לשמור על כבוד המקצוע בלבד', 'חובה לייצג כל מי שפונה אליו', 'חובה כפולה: לפעול לטובת הלקוח בנאמנות ובמסירות ולעזור לבית המשפט לעשות משפט'], 'c': 3, 'e': 'נכון. הסעיף מטיל חובה כלפי השולח וחובה כלפי בית המשפט, והאיזון ביניהן הוא לב האתיקה המקצועית.'}, {'q': 'מהם שלושת תנאי הכשירות להיות עורך דין לפי ס׳ 24?', 'o': ['השכלה משפטית גבוהה, התמחות ועמידה בבחינות הלשכה', 'השכלה משפטית, המלצה של שופט ושנת ותק', 'התמחות, תושבות ואזרחות', 'תואר ראשון בכל תחום, ראיון ובחינה'], 'c': 0, 'e': 'נכון. ס׳ 24 מונה השכלה משפטית גבוהה, תקופת התמחות ועמידה בבחינות.'}, {'q': 'יוסי, רואה חשבון, ניסח עבור לקוח קבוע הסכם שכירות תמורת תשלום. מה הדין?', 'o': ['מדובר בפעולה המיוחדת לעורכי דין, שנעשתה בתמורה — הסגת גבול המקצוע', 'מותר, כי רואה חשבון הוא בעל מקצוע מורשה', 'מותר, כל עוד ההסכם פשוט', 'מותר, כי ההסכם נחתם בין הצדדים ולא הוגש לבית משפט'], 'c': 0, 'e': 'נכון. עריכת מסמך משפטי בשביל אחר בתמורה היא פעולה מיוחדת (ס׳ 20(3)); מי שעושה אותה כשאינו עורך דין עובר עבירה לפי ס׳ 96 ולא יוכל לתבוע שכר (ס׳ 98).'}, {'q': 'שרה, סטודנטית למשפטים, ניסחה בחינם ופעם אחת מכתב התראה לשכנתה. האם עברה על ס׳ 20?', 'o': ['כן, כי כל ניסוח משפטי מיוחד לעורכי דין', 'לא, כי הפעולה לא נעשתה דרך עיסוק ולא בתמורה', 'לא, אבל רק אם המכתב לא נשלח', 'כן, כי היא עדיין לא מתמחה'], 'c': 1, 'e': 'נכון. ס׳ 20 חל על מי שפועל "דרך עיסוק, או בתמורה אף שלא דרך עיסוק". עזרה חד־פעמית ללא תמורה אינה הסגת גבול.'}, {'q': 'מתמחה בחודש הרביעי להתמחותו מבקש לייצג לבדו לקוח של מאמנו בבית משפט השלום. מה הדין?', 'o': ['רשאי, אם הלקוח הסכים', 'אינו רשאי; לפי ס׳ 37 ייצוג אפשרי רק בששת החודשים האחרונים, בנוכחות המאמן או ברשות בית המשפט', 'רשאי, כי מדובר בבית משפט השלום', 'רשאי בכל ערכאה, אם המאמן נוכח'], 'c': 1, 'e': 'נכון. ס׳ 37 מתיר ייצוג רק בששת החודשים האחרונים, רק בשלום, ובתנאי שהמאמן נוכח או שבית המשפט הרשה.'}, {'q': 'נאשם מודה בפני הסנגור שלו שביצע את העבירה, אך מבקש לכפור באשמה. מה הדין לפי כללי האתיקה?', 'o': ['הסנגור חייב לגלות לבית המשפט את ההודאה', 'הסנגור חייב להפסיק את הייצוג מיד', 'הסנגור רשאי להביא עד שיספק לנאשם אליבי', 'הסנגור רשאי לכפור בעובדות ולדרוש מהתביעה להוכיח, אך אסור לו להציג ראיות או עדות שהוא יודע שהן שקריות'], 'c': 3, 'e': 'נכון. כלל 34(ב) מתיר כפירה בעובדה בהליך פלילי, וזו דרישה שהתביעה תעמוד בנטל. האיסור הוא על הצגה אקטיבית של שקר.'}, {'q': 'מה ההבדל בין חובת הסודיות לבין החיסיון?', 'o': ['החיסיון שייך לעורך הדין והוא רשאי לוותר עליו', 'חובת הסודיות חלה רק בבית המשפט, החיסיון חל רק מחוץ לו', 'אין הבדל, אלה שמות שונים לאותו כלל', 'סודיות היא חובה אתית רחבה לשמור בסוד כל מה שהלקוח מסר; חיסיון הוא כלל ראייתי שמונע גילוי דברים שהוחלפו בהליך משפטי, חקירה או חיפוש'], 'c': 3, 'e': 'נכון. כלל 19 קובע חובה רחבה, וס׳ 90 קובע חסינות מפני גילוי בהליכים.'}, {'q': 'עו״ד רון יודע שהצד שכנגד מיוצג. הלקוח שלו מציע שרון יתקשר ישירות לצד השני כדי לסגור פשרה. מה הדין?', 'o': ['אסור לפנות לצד מיוצג אלא דרך עורך דינו, זולת אם עורך דינו הסכים', 'אסור, כי עורך דין לעולם לא מדבר עם הצד שכנגד', 'מותר, אם השיחה מנומסת', 'מותר, אם רון מקליט את השיחה'], 'c': 0, 'e': 'נכון. כלל 25 מחייב פנייה דרך עורך הדין המייצג, אלא בהסכמתו או כשקיימת חובה בדין למסור דבר לצד.'}, {'q': 'עורכת דין כתבה בבקשה לבית המשפט שהשופט "אינו מבין דבר בדיני חוזים ומזלזל בלקוחותיי". מה הניתוח הנכון?', 'o': ['מותר, כי חופש הביטוי מגן על כל ביקורת', 'אסור לעורך דין לבקר החלטות של שופט בשום מקרה', 'מדובר בהתבטאות בגרעין הקשה של המקצוע; ביקורת עניינית מותרת, אך עלבון אישי עלול להוות פגיעה בכבוד בית המשפט ועבירת משמעת', 'מותר, אם הדברים נכונים לדעתה'], 'c': 2, 'e': 'נכון. בגרעין הקשה נדרשים איפוק ונימוס (כלל 32), והתבטאות פוגענית עלולה להיות "מעשה שאינו הולם" לפי ס׳ 61(3).'}, {'q': 'לפי ס׳ 77א לחוק בתי המשפט, מהו המבחן הכללי לפסלות שופט?', 'o': ['כל חשש של בעל דין שהשופט אינו אוהד אותו', 'ודאות שהשופט מוטה', 'השתייכות השופט לאותה קבוצה דתית או לאומית של בעל הדין', 'חשש ממשי למשוא פנים בניהול המשפט'], 'c': 3, 'e': 'נכון. זה לשון ס׳ 77א(א): נסיבות שיש בהן כדי ליצור חשש ממשי למשוא פנים.'}, {'q': 'בעל דין גילה שהשופטת בתיק ייצגה אותו כעורכת דין לפני שלוש שנים בעניין אחר. מה הדין לפי כללי האתיקה לשופטים?', 'o': ['השופטת תשב בדין, אם תצהיר שאינה זוכרת אותו', 'אין בעיה, כי מדובר בעניין אחר', 'השופטת לא תשב בדין, כי בעל דין שהיה לקוחה לפני פחות מחמש שנים הוא עילת פסלות', 'רק נשיא בית המשפט העליון רשאי להחליט'], 'c': 2, 'e': 'נכון. כלל 15(ב)(4) קובע עילה כשבעל הדין היה לקוחו של השופט ולא חלפו חמש שנים מאז הטיפול.'}, {'q': 'שופט מוזמן לנאום בכנס של מפלגה בנושא רפורמה בחינוך. מה הדין?', 'o': ['אסור, אלא אם המפלגה בקואליציה', 'אסור; שופט לא ייטול חלק באירוע שעורכת מפלגה או גוף פוליטי', 'מותר, כי הנושא אינו משפטי', 'מותר, אם לא יזכיר תיקים תלויים'], 'c': 1, 'e': 'נכון. כלל 17 אוסר מעורבות פוליטית ומפלגתית, ובכלל זה השתתפות באירוע של מפלגה.'}, {'q': 'מה תפקידה של ועדת האתיקה לשופטים לפי כלל 41?', 'o': ['לתת חוות דעת מקדימה לשופט שפנה אליה בעניין הנוגע לו', 'לדון בקובלנות ולהטיל עונשים', 'לבחור שופטים חדשים', 'לבטל פסקי דין שניתנו בניגוד לאתיקה'], 'c': 0, 'e': 'נכון. הוועדה נותנת חוות דעת מקדימה לפי פנייה ומפרסמת אותן ללא פרטים מזהים.'}, {'q': 'מה ההבדל המרכזי בין תפקיד התובע לבין תפקיד עורך דין פרטי?', 'o': ['תובע אינו כפוף לכללי האתיקה', 'תובע מייצג את האינטרס הציבורי ותפקידו לקדם עשיית צדק, לא לנצח בכל מחיר', 'תובע רשאי להסתיר ראיות שמזכות את הנאשם', 'אין הבדל, שניהם מייצגים צד'], 'c': 1, 'e': 'נכון. התובע אינו בעל דין רגיל; חובותיו מוגברות, כולל שיקול דעת ענייני והגינות כלפי הנאשם.'}, {'q': 'מה קבע בית המשפט העליון בעניין לוי נ׳ שרמן?', 'o': ['שחוק הלשכה והכללים משמשים מקור לקביעת סטנדרט הזהירות של עורך דין כלפי לקוחו בנזיקין', 'שעורך דין אינו חב בנזיקין כלפי לקוחו', 'שכללי האתיקה אינם רלוונטיים לתביעה אזרחית', 'שרק הלשכה רשאית לפסוק פיצויים נגד עורך דין'], 'c': 0, 'e': 'נכון. נקבע שהנורמות האתיות מעצבות את סטנדרט המיומנות והזהירות בעוולת הרשלנות.'}, {'q': 'מה נקבע בעניין קבוצת גיאות נ׳ גולדפרב לגבי לקוח שמתעקש לפעול בניגוד לעצת עורך הדין?', 'o': ['עורך הדין חייב להתפטר מיד', 'עורך הדין חייב להזהיר ולהסביר את הסיכונים; היקף החובה תלוי בנסיבות, והתפטרות שמורה למקרי קיצון', 'עורך הדין רשאי לפעול לפי שיקול דעתו בניגוד לרצון הלקוח', 'עורך הדין חייב לבצע את רצון הלקוח בלי לומר דבר'], 'c': 1, 'e': 'נכון. אמות המידה הן זהות הלקוח ומעורבותו, גודל הסיכון ומורכבות הסוגיה.'}, {'q': 'מהי נוסחת האיזון שנקבעה בעניין שפטל?', 'o': ['רק התבטאויות בכתב נבחנות', 'ככל שההתבטאות קרובה יותר לגרעין הקשה של המקצוע נדרש איפוק רב יותר; ככל שהיא רחוקה ממנו, גובר משקל חופש הביטוי', 'חופש הביטוי של עורך דין מוחלט', 'עורך דין אינו רשאי להתבטא בנושאים פוליטיים'], 'c': 1, 'e': 'נכון. זו נוסחת "הגרעין הקשה", ובנסיבות שפטל ההתבטאות הפרטית לא נחשבה עבירה.'}, {'q': 'איזה עונש אינו בסמכות בית דין משמעתי של הלשכה לפי ס׳ 68?', 'o': ['מאסר', 'הוצאה מן הלשכה', 'השעיה לתקופה של עד עשר שנים', 'נזיפה'], 'c': 0, 'e': 'נכון. מאסר הוא עונש פלילי שמוטל רק בבית משפט; בית דין משמעתי מוגבל לאזהרה, נזיפה, קנס, השעיה והוצאה.'}, {'q': 'לפי לשון כלל 34(א), מה אסור על עורך דין?', 'o': ['להכחיש עובדות בכתב הגנה', 'להעלות טענה עובדתית או משפטית ביודעו שאינה נכונה, בין בעל פה ובין בכתב', 'להעלות טענה שלא התקבלה בעבר בפסיקה', 'לטעון טענה חלשה'], 'c': 1, 'e': 'נכון. זה לשון כלל 34(א), שחל על טיעון בעל פה ובכתב.'}, {'q': 'לפי ס׳ 61(3) לחוק הלשכה, מהי עבירת משמעת?', 'o': ['כל מעשה או מחדל אחר שאינו הולם את מקצוע עריכת הדין', 'רק הפרה של כלל אתיקה כתוב', 'רק התנהגות בבית המשפט', 'רק עבירה פלילית שבוצעה במסגרת העבודה'], 'c': 0, 'e': 'נכון. זו עילת סל שמאפשרת להעמיד לדין משמעתי גם על התנהגות שלא נמנתה במפורש.'}]
